package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.config.*;
import it.cavallium.rockserver.core.impl.rocksdb.*;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.time.Duration;
import java.util.*;

/** Stable local physical placement and frozen effective native configuration. */
public final class RatisNativePoolSpec {
    public static final int MAX_CONFIG_BYTES=1024*1024,MAX_BYTES=MAX_CONFIG_BYTES+192;
    private final UUID id;private final byte[] configuration,encoded;private final DatabaseConfig config;
    private final int maximumGroups;private final NativeRangeImage.Limits images;private final RatisRangeStateMachine.RetentionLimits retention;private final PoolSnapshotAdmission.Limits pins;private final RatisSchemaReplicaService.Limits replicas;private final RatisNodeResourceBudget.Limits resources;
    public RatisNativePoolSpec(UUID id,byte[] configuration,int maximumGroups,NativeRangeImage.Limits images,RatisRangeStateMachine.RetentionLimits retention,PoolSnapshotAdmission.Limits pins,RatisSchemaReplicaService.Limits replicas,RatisNodeResourceBudget.Limits resources){
        this.id=Objects.requireNonNull(id);this.maximumGroups=maximumGroups;this.images=Objects.requireNonNull(images);this.retention=Objects.requireNonNull(retention);this.pins=Objects.requireNonNull(pins);this.replicas=Objects.requireNonNull(replicas);this.resources=Objects.requireNonNull(resources);
        if(maximumGroups<1 || maximumGroups>RatisNodePlan.MAX_LOCAL_GROUPS)throw new IllegalArgumentException("Invalid physical pool group ceiling");var parser=new ConfigParser();parser.addSourceBytes(configuration);config=parser.parse();this.configuration=("database="+ConfigPrinter.stringify(config)).getBytes(StandardCharsets.UTF_8);if(this.configuration.length>MAX_CONFIG_BYTES)throw new IllegalArgumentException("Effective pool configuration exceeds bound");encoded=encodeFields();
    }
    public UUID id(){return id;}public byte[] configuration(){return configuration.clone();}public DatabaseConfig config(){return config;}public int maximumGroups(){return maximumGroups;}public NativeRangeImage.Limits images(){return images;}public RatisRangeStateMachine.RetentionLimits retention(){return retention;}public PoolSnapshotAdmission.Limits pins(){return pins;}public RatisSchemaReplicaService.Limits replicas(){return replicas;}public RatisNodeResourceBudget.Limits resources(){return resources;}
    public Path nativePath(Path nodeRoot){return nodeRoot.resolve("native").resolve(id.toString());}
    public byte[] encode(){return encoded.clone();}
    private byte[] encodeFields(){var out=ByteBuffer.allocate(configuration.length+192);out.putLong(id.getMostSignificantBits()).putLong(id.getLeastSignificantBits()).putInt(configuration.length).put(configuration).putInt(maximumGroups);out.putInt(images.maxRowBytes()).putLong(images.maxImageBytes()).putInt(images.maxColumns());out.putLong(retention.dataCount()).putLong(retention.dataBytes()).putLong(retention.maintenanceCount()).putLong(retention.maintenanceBytes());out.putInt(pins.maximumPins()).putLong(pins.maximumEstimatedBytes()).putLong(pins.maximumAge().toNanos()).putLong(pins.minimumFreeBytes());out.putInt(replicas.maximumUploads()).putLong(replicas.maximumDiskBytes()).putLong(replicas.maximumHeapBytes()).putInt(replicas.maximumTasks()).putInt(replicas.maximumObservers()).putLong(replicas.minimumFreeBytes());for(var lane:List.of(resources.ordinary(),resources.protectedLane()))out.putLong(lane.bytes()).putInt(lane.owners());return Arrays.copyOf(out.array(),out.position());}
    public static RatisNativePoolSpec decode(byte[] bytes){if(bytes==null || bytes.length<161 || bytes.length>MAX_BYTES)throw new IllegalArgumentException("Invalid native pool declaration");try{var in=ByteBuffer.wrap(bytes);var id=new UUID(in.getLong(),in.getLong());int length=in.getInt();if(length<1 || length>MAX_CONFIG_BYTES || length>in.remaining()-140)throw new IllegalArgumentException("Invalid native configuration length");var config=new byte[length];in.get(config);int groups=in.getInt();var images=new NativeRangeImage.Limits(in.getInt(),in.getLong(),in.getInt());var retention=new RatisRangeStateMachine.RetentionLimits(in.getLong(),in.getLong(),in.getLong(),in.getLong());var pins=new PoolSnapshotAdmission.Limits(in.getInt(),in.getLong(),Duration.ofNanos(in.getLong()),in.getLong());var replicas=new RatisSchemaReplicaService.Limits(in.getInt(),in.getLong(),in.getLong(),in.getInt(),in.getInt(),in.getLong());var ordinary=new RatisNodeResourceBudget.Lane(in.getLong(),in.getInt());var protectedLane=new RatisNodeResourceBudget.Lane(in.getLong(),in.getInt());var result=new RatisNativePoolSpec(id,config,groups,images,retention,pins,replicas,new RatisNodeResourceBudget.Limits(ordinary,protectedLane));if(in.hasRemaining() || !Arrays.equals(bytes,result.encoded))throw new IllegalArgumentException("Noncanonical native pool declaration");return result;}catch(java.nio.BufferUnderflowException truncated){throw new IllegalArgumentException("Truncated native pool declaration",truncated);}}
    @Override public boolean equals(Object other){return other instanceof RatisNativePoolSpec spec && Arrays.equals(encoded,spec.encoded);}@Override public int hashCode(){return Arrays.hashCode(encoded);}
}
